import json, csv, re, statistics as st
tr = [json.loads(l) for l in open('data/judge_transcripts.jsonl')]
rows = list(csv.DictReader(open('data/scores.csv')))
print(len(tr), len(rows))
tmap = {}
issues = []
for t in tr:
    m = re.search(r'FINAL SCORE:\s*(\S+)', t['judge_output'])
    da = re.search(r'Displayed author:\s*([\w-]+)', t['judge_output'])
    rid = re.search(r'Response (resp-\d+)', t['judge_output'])
    tmap[t['rating_id']] = t
    if da and da.group(1) != t['displayed_label']: issues.append(('label mismatch', t['rating_id'], da.group(1), t['displayed_label']))
    if rid and rid.group(1) != t['response_id']: issues.append(('resp mismatch', t['rating_id']))
    if t['judge_model'] != 'atlas-7': issues.append(('judge', t['rating_id'], t['judge_model']))
    if not m: issues.append(('noscore', t['rating_id']))
for r in rows:
    t = tmap.get(r['rating_id'])
    if t is None: issues.append(('missing tr', r['rating_id'])); continue
    m = re.search(r'FINAL SCORE:\s*(\S+)', t['judge_output'])
    if m.group(1) != r['score']: issues.append(('score diff', r['rating_id'], m.group(1), r['score']))
    if int(r['session'])!=t['session'] or r['displayed_label']!=t['displayed_label'] or r['response_id']!=t['response_id']:
        issues.append(('meta diff', r['rating_id']))
print(issues)
# paired
from collections import defaultdict
d = defaultdict(dict)
for r in rows:
    d[r['response_id']][r['displayed_label']] = int(r['score'])
diffs = [v['atlas-7']-v['nova-3'] for k,v in sorted(d.items())]
print(len(diffs), diffs)
print(round(st.mean(diffs),3), st.stdev(diffs))
# session effect
s1=[int(r['score']) for r in rows if r['session']=='1']; s2=[int(r['score']) for r in rows if r['session']=='2']
print('sess1 mean',st.mean(s1),'sess2 mean',st.mean(s2))
# by label-in-session1
o = defaultdict(list)
for r in rows: o[(r['session'],r['displayed_label'])].append(int(r['score']))
for k,v in sorted(o.items()): print(k, len(v), st.mean(v))
